fn count_multiples_of_3_or_5(n: int) to int {
    let mut sum: int = 0
    let mut i: int = 1
    while i < n {
        if i % 3 == 0 or i % 5 == 0 {
            sum = sum + i
        }
        i = i + 1
    }
    return sum
}

fn matrix_row_sums(matrix: list[list[int]]) to list[int] {
    let mut sums: list[int] = []
    let mut i: int = 0
    while i < matrix.len() {
        let row: list[int] = matrix[i].unwrap()
        let mut s: int = 0
        let mut j: int = 0
        while j < row.len() {
            s = s + row[j].unwrap()
            j = j + 1
        }
        sums = sums.push(s)
        i = i + 1
    }
    return sums
}

benchmarks.test_harness:
fn __vox_eval_harness() to str {
    assert(matrix_row_sums([[1, 2, 3], [4, 5, 6]]) == [6, 15])
    assert(matrix_row_sums([[-2, 5], [0, 0], [10]]) == [3, 0, 10])
    assert(matrix_row_sums([]) == [])
    return "ok"
}

