fn matrix_col_sums(matrix: list[list[int]]) to list[int] {
    if matrix.len() == 0 {
        return []
    }
    let mut sums: list[int] = []
    let cols: int = matrix[0].unwrap().len()
    let mut c: int = 0
    while c < cols {
        let mut s: int = 0
        let mut r: int = 0
        while r < matrix.len() {
            s = s + matrix[r].unwrap()[c].unwrap()
            r = r + 1
        }
        sums = sums.push(s)
        c = c + 1
    }
    return sums
}

