fn is_symmetric_matrix(matrix: list[list[int]]) to bool {
    let n: int = matrix.len()
    let mut i: int = 0
    while i < n {
        let mut j: int = 0
        while j < n {
            if matrix[i].unwrap()[j].unwrap() != matrix[j].unwrap()[i].unwrap() {
                return false
            }
            j = j + 1
        }
        i = i + 1
    }
    return true
}

type CharCount =
    | CharCount(ch: str, count: int)

fn char_histogram(s: str) to list[CharCount] {
    let mut keys: list[str] = []
    let mut counts: list[int] = []
    let mut i: int = 0
    while i < s.len() {
        let ch: str = s.slice(i, i + 1)
        let mut found: bool = false
        let mut k: int = 0
        while k < keys.len() {
            if keys[k].unwrap() == ch {
                counts[k] = counts[k].unwrap() + 1
                found = true
            }
            k = k + 1
        }
        if not found {
            keys = keys.push(ch)
            counts = counts.push(1)
        }
        i = i + 1
    }
    let mut out: list[CharCount] = []
    let mut m: int = 0
    while m < keys.len() {
        out = out.push(CharCount(keys[m].unwrap(), counts[m].unwrap()))
        m = m + 1
    }
    return out
}

benchmarks.test_harness:
fn __vox_eval_harness() to str {
    assert(char_histogram("abca") == [CharCount("a", 2), CharCount("b", 1), CharCount("c", 1)])
    assert(char_histogram("") == [])
    return "ok"
}

