fn longest_increasing_run(nums: list[int]) to int {
    if nums.len() == 0 {
        return 0
    }
    let mut best: int = 1
    let mut cur: int = 1
    let mut i: int = 1
    while i < nums.len() {
        if nums[i].unwrap() > nums[i - 1].unwrap() {
            cur = cur + 1
        } else {
            cur = 1
        }
        if cur > best {
            best = cur
        }
        i = i + 1
    }
    return best
}

fn is_valid_ipv4(s: str) to bool {
    let parts: list[str] = s.split(".")
    if parts.len() != 4 {
        return false
    }
    let mut i: int = 0
    while i < 4 {
        let part: str = parts[i].unwrap()
        if not part.is_digit() {
            return false
        }
        match part.to_int() {
            Some(n) => {
                if n < 0 or n > 255 {
                    return false
                }
            }
            None => { return false }
        }
        i = i + 1
    }
    return true
}

fn string_is_rotation(a: str, b: str) to bool {
    if a.len() != b.len() {
        return false
    }
    let doubled: str = a + a
    return doubled.contains(b)
}

fn balanced_multi_brackets(s: str) to bool {
    let mut stack: list[str] = []
    let chars: list[str] = s.chars()
    let mut i: int = 0
    while i < chars.len() {
        let ch: str = chars[i].unwrap()
        if ch == "(" or ch == "[" or ch == "{" {
            stack = stack.push(ch)
        } else if ch == ")" or ch == "]" or ch == "}" {
            if stack.len() == 0 {
                return false
            }
            let top: str = stack[stack.len() - 1].unwrap()
            let matches: bool = (ch == ")" and top == "(") or (ch == "]" and top == "[") or (ch == "}" and top == "{")
            if not matches {
                return false
            }
            stack = stack.remove_at(stack.len() - 1)
        }
        i = i + 1
    }
    return stack.len() == 0
}

fn count_words_starting_with(s: str, letter: str) to int {
    let words: list[str] = s.split(" ")
    let mut count: int = 0
    let mut i: int = 0
    while i < words.len() {
        let w: str = words[i].unwrap()
        if w.len() > 0 and w.slice(0, 1) == letter {
            count = count + 1
        }
        i = i + 1
    }
    return count
}

benchmarks.test_harness:
fn __vox_eval_harness() to str {
    assert(count_words_starting_with("alpha beta apricot", "a") == 2)
    assert(count_words_starting_with("  one  two  ", "t") == 1)
    assert(count_words_starting_with("", "a") == 0)
    return "ok"
}

