fn weighted_average(values: list[int], weights: list[int]) to float {
    let mut total: float = 0.0
    let mut weight_sum: float = 0.0
    let mut i: int = 0
    while i < values.len() {
        let v: float = float(values[i].unwrap())
        let w: float = float(weights[i].unwrap())
        total = total + v * w
        weight_sum = weight_sum + w
        i = i + 1
    }
    return total / weight_sum
}

benchmarks.test_harness:
fn __vox_eval_harness() to str {
    let a: float = weighted_average([10, 20], [1, 3])
    assert(a > 17.49 and a < 17.51)
    let b: float = weighted_average([5, 5, 5], [2, 2, 2])
    assert(b > 4.99 and b < 5.01)
    let c: float = weighted_average([0, 100], [9, 1])
    assert(c > 9.99 and c < 10.01)
    return "ok"
}

