fn dedupe_case_insensitive(items: list[str]) to list[str] {
    let mut seen: list[str] = []
    let mut out: list[str] = []
    let mut i: int = 0
    while i < items.len() {
        let lower: str = items[i].unwrap().to_lower()
        if not seen.contains(lower) {
            seen = seen.push(lower)
            out = out.push(items[i].unwrap())
        }
        i = i + 1
    }
    return out
}

