fn selection_sort(xs: list[int]) to list[int] {
    let n: int = xs.len()
    let mut arr: list[int] = []
    for x in xs {
        arr.push(x)
    }
    let mut i: int = 0
    while i < n {
        let mut min_idx: int = i
        let mut j: int = i + 1
        while j < n {
            match arr[j] {
                Some(vj) => {
                    match arr[min_idx] {
                        Some(vm) => {
                            if vj < vm {
                                min_idx = j
                            }
                        }
                        None => {}
                    }
                }
                None => {}
            }
            j = j + 1
        }
        match arr[i] {
            Some(vi) => {
                match arr[min_idx] {
                    Some(vm) => {
                        arr[i] = vm
                        arr[min_idx] = vi
                    }
                    None => {}
                }
            }
            None => {}
        }
        i = i + 1
    }
    return arr
}

