    let mut result: str = ""
    let chars: list[str] = s.chars()
    for c in chars {
        let code: int = c.ord()
        if code >= 97 and code <= 122 {
            let new_code: int = (code - 97 + shift) % 26 + 97
            result = result + chr(new_code)
