fn mod_pow(base: int, exp: int, modulus: int) to int {
    if modulus == 1 {
        return 0
    }
    let mut res: int = 1
    let mut b: int = ((base % modulus) + modulus) % modulus
    let mut e: int = exp
    while e > 0 {
        if e % 2 == 1 {
            res = (res * b) % modulus
        }
        e = e / 2
        b = (b * b) % modulus
    }
    return res
