    let mut result: int = n
    let mut rem: int = n
    let mut p: int = 2
    while p * p <= rem {
        if rem % p == 0 {
            while rem % p == 0 {
                rem = rem / p
            }
            result = result - result / p
        }
        p = p + 1
    }
    if rem > 1 {
        result = result - result / rem
    }
    return result
}

