fn coin_change_min(coins: list[int], amount: int) to int {
    if amount < 0 {
        return -1
    }
    if amount == 0 {
        return 0
    }
    let inf: int = amount + 1
    let mut dp: list[int] = [0]
    let mut a: int = 1
    while a <= amount {
        dp = dp.push(inf)
        a = a + 1
    }
    a = 1
    while a <= amount {
        let mut best: int = inf
        for c in coins {
            if c > 0 and c <= a {
                let cand: int = dp[a - c].unwrap() + 1
                if cand < best {
                    best = cand
                }
            }
        }
        dp[a] = best
        a = a + 1
    }
    let ans: int = dp[amount].unwrap()
    if ans >= inf {
        return -1
    }
    return ans
}

