fn knapsack_01(weights: list[int], values: list[int], cap: int) to int {
    if cap <= 0 {
        return 0
    }
    let mut dp: list[int] = []
    let mut w: int = 0
    while w <= cap { dp = dp.push(0)
 w = w + 1 }
    let mut i: int = 0
    while i < weights.len() {
        let wt: int = weights[i].unwrap()
        let val: int = values[i].unwrap()
        let mut c: int = cap
        while c >= wt {
            let cand: int = dp[c - wt].unwrap() + val
            if cand > dp[c].unwrap() {
                dp[c] = cand
            }
            c = c - 1
        }
        i = i + 1
    }
    return dp[cap].unwrap()
}

