fn eval_min_stack(ops: list[str]) to list[int] {
    let mut mins: list[int] = []
    let mut out: list[int] = []
    for op in ops {
        if op.starts_with("push:") {
            let parts: list[str] = op.split(":")
            match parts[1].unwrap().to_int() {
                Some(v) => {
                    if mins.len() == 0 {
                        mins = mins.push(v)
                    } else {
                        let cur: int = mins[mins.len() - 1].unwrap()
                        if v < cur { mins = mins.push(v) } else { mins = mins.push(cur) }
                    }
                }
                None => {}
            }
        } else if op == "pop" {
            if mins.len() > 0 {
                mins = mins.remove_at(mins.len() - 1)
            }
        } else if op == "min" {
            if mins.len() > 0 {
                out = out.push(mins[mins.len() - 1].unwrap())
            }
        }
    }
    return out
}

