fn count_lru_hits(keys: list[int], capacity: int) to int {
    if capacity <= 0 {
        return 0
    }
    let mut order: list[int] = []
    let mut hits: int = 0
    for k in keys {
        let idx: int = order.index(k)
        if idx >= 0 {
            hits = hits + 1
            order = order.remove_at(idx)
            order = order.push(k)
        } else {
            if order.len() >= capacity {
                order = order.remove_at(0)
            }
            order = order.push(k)
        }
    }
    return hits
}

fn is_valid_stack_sequence(pushed: list[int], popped: list[int]) to bool {
    let mut st: list[int] = []
    let mut j: int = 0
    for x in pushed {
        st = st.push(x)
        while st.len() > 0 and j < popped.len() and st[st.len() - 1].unwrap() == popped[j].unwrap() {
            st = st.remove_at(st.len() - 1)
            j = j + 1
        }
    }
    return j == popped.len() and st.len() == 0
}

