    let mut i: int = 0
    while i < n {
        let h: int = heights[i].unwrap()
        let mut l: int = i
        while l > 0 and heights[l - 1].unwrap() >= h {
            l = l - 1
        }
        let mut r: int = i
        while r + 1 < n and heights[r + 1].unwrap() >= h {
            r = r + 1
        }
        let area: int = h * (r - l + 1)
        if area > best {
            best = area
        }
        i = i + 1
    }
    return best
}

