fn max_non_overlapping(starts: list[int], ends: list[int]) to int {
    let n: int = starts.len()
    if n == 0 {
        return 0
    }
    let mut used: list[bool] = []
    let mut i: int = 0
    while i < n { used = used.push(false)
 i = i + 1 }
    let mut count: int = 0
    let mut last_end: int = -1000000000
    let mut step: int = 0
    while step < n {
        let mut best_idx: int = -1
        let mut best_end: int = 1000000000
        i = 0
        while i < n {
            if not used[i].unwrap() and starts[i].unwrap() >= last_end and ends[i].unwrap() < best_end {
                best_end = ends[i].unwrap()
                best_idx = i
            }
            i = i + 1
        }
        if best_idx == -1 {
            return count
        }
        used[best_idx] = true
        last_end = best_end
        count = count + 1
        step = step + 1
    }
    return count
}

