fn count_components(n: int, edges: list[list[int]]) to int {
    let mut parent: list[int] = []
    let mut i: int = 0
    while i < n { parent = parent.push(i)
 i = i + 1 }
    for e in edges {
        let mut u: int = e[0].unwrap()
        let mut v: int = e[1].unwrap()
        while parent[u].unwrap() != u { u = parent[u].unwrap() }
        while parent[v].unwrap() != v { v = parent[v].unwrap() }
        if u != v {
            parent[v] = u
        }
    }
    let mut roots: int = 0
    i = 0
    while i < n {
        if parent[i].unwrap() == i {
            roots = roots + 1
        }
        i = i + 1
    }
    return roots
}

fn shortest_hops(n: int, edges: list[list[int]], src: int, dst: int) to int {
    if src < 0 or src >= n or dst < 0 or dst >= n { return -1 }
    if src == dst { return 0 }
    let mut dist: list[int] = []
    let mut i: int = 0
    while i < n { dist = dist.push(-1)
 i = i + 1 }
    dist[src] = 0
    let mut q: list[int] = [src]
    let mut head: int = 0
    while head < q.len() {
        let u: int = q[head].unwrap()
        head = head + 1
        let d: int = dist[u].unwrap()
        for e in edges {
            let a: int = e[0].unwrap()
            let b: int = e[1].unwrap()
            let mut nxt: int = -1
            if a == u { nxt = b } else if b == u { nxt = a }
            if nxt >= 0 and dist[nxt].unwrap() == -1 {
                dist[nxt] = d + 1
                if nxt == dst { return d + 1 }
                q = q.push(nxt)
            }
        }
    }
    return -1
}

