fn simulate_ring_buffer(cap: int, ops: list[str]) to list[int] {
    let mut q: list[int] = []
    let mut out: list[int] = []
    for op in ops {
        if op.starts_with("enq:") {
            if q.len() < cap {
                let p: list[str] = op.split(":")
                match p[1].unwrap().to_int() {
                    Some(v) => { q = q.push(v) }
                    None => {}
                }
            }
        } else if op == "deq" {
            if q.len() == 0 {
                out = out.push(-1)
            } else {
                out = out.push(q[0].unwrap())
                q = q.remove_at(0)
            }
        }
    }
    return out
}

