fn sparse_dot(idx_a: list[int], val_a: list[int], idx_b: list[int], val_b: list[int]) to int {
    let mut i: int = 0
    let mut j: int = 0
    let mut sum: int = 0
    while i < idx_a.len() and j < idx_b.len() {
        let ia: int = idx_a[i].unwrap()
        let ib: int = idx_b[j].unwrap()
        if ia == ib {
            sum = sum + val_a[i].unwrap() * val_b[j].unwrap()
            i = i + 1
            j = j + 1
        } else if ia < ib {
            i = i + 1
        } else {
            j = j + 1
        }
    }
    return sum
}

