fn is_valid_toposort(n: int, edges: list[list[int]], order: list[int]) to bool {
    if order.len() != n {
        return false
    }
    let mut pos: list[int] = []
    let mut i: int = 0
    while i < n { pos = pos.push(-1)
 i = i + 1 }
    i = 0
    while i < n {
        let node: int = order[i].unwrap()
        if node < 0 or node >= n or pos[node].unwrap() != -1 {
            return false
        }
        pos[node] = i
        i = i + 1
    }
    for e in edges {
        let u: int = e[0].unwrap()
        let v: int = e[1].unwrap()
        if pos[u].unwrap() >= pos[v].unwrap() {
            return false
        }
    }
    return true
}

