fn has_directed_cycle(n: int, edges: list[list[int]]) to bool {
    let mut indeg: list[int] = []
    let mut i: int = 0
    while i < n { indeg = indeg.push(0)
 i = i + 1 }
    for e in edges {
        let v: int = e[1].unwrap()
        indeg[v] = indeg[v].unwrap() + 1
    }
    let mut q: list[int] = []
    i = 0
    while i < n {
        if indeg[i].unwrap() == 0 { q = q.push(i) }
        i = i + 1
    }
    let mut visited: int = 0
    let mut head: int = 0
    while head < q.len() {
        let u: int = q[head].unwrap()
        head = head + 1
        visited = visited + 1
        for e in edges {
            if e[0].unwrap() == u {
                let v: int = e[1].unwrap()
                let next_d: int = indeg[v].unwrap() - 1
                indeg[v] = next_d
                if next_d == 0 { q = q.push(v) }
            }
        }
    }
    return visited != n
}

