fn spiral_order(grid: list[list[int]]) to list[int] {
    if grid.len() == 0 { return [] }
    let mut top: int = 0
    let mut bottom: int = grid.len() - 1
    let mut left: int = 0
    let mut right: int = grid[0].unwrap().len() - 1
    let mut out: list[int] = []
    while top <= bottom and left <= right {
        let mut c: int = left
        while c <= right { out = out.push(grid[top].unwrap()[c].unwrap())
 c = c + 1 }
        top = top + 1
        let mut r: int = top
        while r <= bottom { out = out.push(grid[r].unwrap()[right].unwrap())
 r = r + 1 }
        right = right - 1
        if top <= bottom {
            c = right
            while c >= left { out = out.push(grid[bottom].unwrap()[c].unwrap())
 c = c - 1 }
            bottom = bottom - 1
        }
        if left <= right {
            r = bottom
            while r >= top { out = out.push(grid[r].unwrap()[left].unwrap())
 r = r - 1 }
            left = left + 1
        }
    }
    return out
}

