fn count_islands(grid: list[list[int]]) to int {
    let rows: int = grid.len()
    if rows == 0 { return 0 }
    let cols: int = grid[0].unwrap().len()
    let mut vis: list[bool] = []
    let mut k: int = 0
    while k < rows * cols { vis = vis.push(false)
 k = k + 1 }
    let mut islands: int = 0
    let mut r: int = 0
    while r < rows {
        let mut c: int = 0
        while c < cols {
            let idx: int = r * cols + c
            if grid[r].unwrap()[c].unwrap() == 1 and not vis[idx].unwrap() {
                islands = islands + 1
                vis[idx] = true
                let mut qr: list[int] = [r]
                let mut qc: list[int] = [c]
                let mut head: int = 0
                while head < qr.len() {
                    let cr: int = qr[head].unwrap()
                    let cc: int = qc[head].unwrap()
                    head = head + 1
                    let drs: list[int] = [-1, 1, 0, 0]
                    let dcs: list[int] = [0, 0, -1, 1]
                    let mut d: int = 0
                    while d < 4 {
                        let nr: int = cr + drs[d].unwrap()
                        let nc: int = cc + dcs[d].unwrap()
                        if nr >= 0 and nr < rows and nc >= 0 and nc < cols {
                            let nidx: int = nr * cols + nc
                            if grid[nr].unwrap()[nc].unwrap() == 1 and not vis[nidx].unwrap() {
                                vis[nidx] = true
                                qr = qr.push(nr)
                                qc = qc.push(nc)
                            }
                        }
                        d = d + 1
                    }
                }
            }
            c = c + 1
        }
        r = r + 1
    }
    return islands
}

