fn grid_shortest_path(grid: list[list[int]]) to int {
    let rows: int = grid.len()
    if rows == 0 { return -1 }
    let cols: int = grid[0].unwrap().len()
    if cols == 0 or grid[0].unwrap()[0].unwrap() == 1 or grid[rows - 1].unwrap()[cols - 1].unwrap() == 1 { return -1 }
    if rows == 1 and cols == 1 { return 0 }
    let mut dist: list[int] = []
    let mut k: int = 0
    while k < rows * cols { dist = dist.push(-1)
 k = k + 1 }
    dist[0] = 0
    let mut qr: list[int] = [0]
    let mut qc: list[int] = [0]
    let mut head: int = 0
    while head < qr.len() {
        let r: int = qr[head].unwrap()
        let c: int = qc[head].unwrap()
        head = head + 1
        let d0: int = dist[r * cols + c].unwrap()
        let drs: list[int] = [-1, 1, 0, 0]
        let dcs: list[int] = [0, 0, -1, 1]
        let mut d: int = 0
        while d < 4 {
            let nr: int = r + drs[d].unwrap()
            let nc: int = c + dcs[d].unwrap()
            if nr >= 0 and nr < rows and nc >= 0 and nc < cols {
                let idx: int = nr * cols + nc
                if grid[nr].unwrap()[nc].unwrap() == 0 and dist[idx].unwrap() == -1 {
                    dist[idx] = d0 + 1
                    if nr == rows - 1 and nc == cols - 1 { return d0 + 1 }
                    qr = qr.push(nr)
                    qc = qc.push(nc)
                }
            }
            d = d + 1
        }
    }
    return -1
}

