fn flood_fill(image: list[list[int]], sr: int, sc: int, new_color: int) to list[list[int]] {
    let rows: int = image.len()
    if rows == 0 { return [] }
    let cols: int = image[0].unwrap().len()
    let orig: int = image[sr].unwrap()[sc].unwrap()
    let mut flat: list[int] = []
    let mut r: int = 0
    while r < rows {
        let mut c: int = 0
        while c < cols {
            flat = flat.push(image[r].unwrap()[c].unwrap())
