        r = r + 1
    }
    if orig != new_color {
        let mut qr: list[int] = [sr]
        let mut qc: list[int] = [sc]
        flat[sr * cols + sc] = new_color
        let mut head: int = 0
        while head < qr.len() {
            let cr: int = qr[head].unwrap()
            let cc: int = qc[head].unwrap()
            head = head + 1
            let drs: list[int] = [-1, 1, 0, 0]
            let dcs: list[int] = [0, 0, -1, 1]
            let mut d: int = 0
            while d < 4 {
                let nr: int = cr + drs[d].unwrap()
                let nc: int = cc + dcs[d].unwrap()
                if nr >= 0 and nr < rows and nc >= 0 and nc < cols {
                    if flat[nr * cols + nc].unwrap() == orig {
                        flat[nr * cols + nc] = new_color
                        qr = qr.push(nr)
                        qc = qc.push(nc)
                    }
                }
                d = d + 1
            }
        }
    }
    let mut out: list[list[int]] = []
    r = 0
    while r < rows {
        let mut row: list[int] = []
        let mut c: int = 0
        while c < cols {
            row = row.push(flat[r * cols + c].unwrap())
            c = c + 1
        }
        out = out.push(row)
        r = r + 1
    }
    return out
}

fn is_toeplitz(matrix: list[list[int]]) to bool {
    let rows: int = matrix.len()
    if rows <= 1 { return true }
    let cols: int = matrix[0].unwrap().len()
    let mut r: int = 1
    while r < rows {
        let mut c: int = 1
        while c < cols {
            if matrix[r].unwrap()[c].unwrap() != matrix[r - 1].unwrap()[c - 1].unwrap() {
                return false
            }
            c = c + 1
        }
        r = r + 1
    }
    return true
}

