fn is_valid_4x4_sudoku(board: list[list[int]]) to bool {
    if board.len() != 4 { return false }
    let mut r: int = 0
    while r < 4 {
        if not is_valid_four(board[r].unwrap()) { return false }
        r = r + 1
    }
    let mut c: int = 0
    while c < 4 {
        let col: list[int] = [board[0].unwrap()[c].unwrap(), board[1].unwrap()[c].unwrap(), board[2].unwrap()[c].unwrap(), board[3].unwrap()[c].unwrap()]
        if not is_valid_four(col) { return false }
        c = c + 1
    }
    let mut br: int = 0
    while br < 4 {
        let mut bc: int = 0
        while bc < 4 {
            let box_vals: list[int] = [board[br].unwrap()[bc].unwrap(), board[br].unwrap()[bc + 1].unwrap(), board[br + 1].unwrap()[bc].unwrap(), board[br + 1].unwrap()[bc + 1].unwrap()]
            if not is_valid_four(box_vals) { return false }
            bc = bc + 2
        }
        br = br + 2
    }
    return true
}

