fn parse_ini_value(doc: str, target_key: str) to str {
    let lines: list[str] = doc.split("\n")
    for raw in lines {
        let line: str = raw.trim()
        if line.len() == 0 or line.starts_with("#") or line.starts_with(";") {
            continue
        }
        match line.index_of("=") {
            Some(pos) => {
                let k: str = line.slice(0, pos).trim()
                if k == target_key {
                    return line.slice(pos + 1, line.chars_count()).trim()
                }
            }
            None => {}
        }
    }
    return ""
}

fn parse_query_param(query_str: str, key: str) to str {
    let mut q: str = query_str
    if q.starts_with("?") {
        q = q.slice(1, q.chars_count())
    }
    let mut found: str = ""
    for pair in q.split("&") {
        match pair.index_of("=") {
            Some(pos) => {
                if pair.slice(0, pos) == key {
                    found = pair.slice(pos + 1, pair.chars_count())
                }
            }
            None => {}
        }
    }
    return found
}

