fn parse_csv_line(line: str) to list[str] {
    if line.len() == 0 { return [] }
    let chars: list[str] = line.chars()
    let mut out: list[str] = []
    let mut cur: str = ""
    let mut in_quotes: bool = false
    let mut i: int = 0
    while i < chars.len() {
        let ch: str = chars[i].unwrap()
        if in_quotes {
            if ch == "\"" {
                if i + 1 < chars.len() and chars[i + 1].unwrap() == "\"" {
                    cur = cur + "\""
                    i = i + 1
                } else {
                    in_quotes = false
                }
            } else {
                cur = cur + ch
            }
        } else {
            if ch == "\"" {
                in_quotes = true
            } else if ch == "," {
                out = out.push(cur)
                cur = ""
            } else {
                cur = cur + ch
            }
        }
        i = i + 1
    }
    out = out.push(cur)
    return out
}

