fn valid_tag_nesting(s: str) to bool {
    let chars: list[str] = s.chars()
    let n: int = chars.len()
    let mut st: list[str] = []
    let mut i: int = 0
    while i < n {
        if chars[i].unwrap() == "<" {
            let mut j: int = i + 1
            let mut tag: str = ""
            let mut closing: bool = false
            if j < n and chars[j].unwrap() == "/" {
                closing = true
                j = j + 1
            }
            while j < n and chars[j].unwrap() != ">" {
                tag = tag + chars[j].unwrap()
                j = j + 1
            }
            if j >= n or tag.len() == 0 { return false }
            if closing {
                if st.len() == 0 or st[st.len() - 1].unwrap() != tag { return false }
                st = st.remove_at(st.len() - 1)
            } else {
                st = st.push(tag)
            }
            i = j
        }
        i = i + 1
    }
    return st.len() == 0
}

fn match_glob(pattern: str, text: str) to bool {
    let p: list[str] = pattern.chars()
    let s: list[str] = text.chars()
    let mut pi: int = 0
    let mut si: int = 0
    let mut star_idx: int = -1
    let mut match_idx: int = 0
    while si < s.len() {
        if pi < p.len() and (p[pi].unwrap() == "?" or p[pi].unwrap() == s[si].unwrap()) {
            pi = pi + 1
            si = si + 1
        } else if pi < p.len() and p[pi].unwrap() == "*" {
            star_idx = pi
            match_idx = si
            pi = pi + 1
        } else if star_idx != -1 {
            pi = star_idx + 1
            match_idx = match_idx + 1
            si = match_idx
        } else {
            return false
        }
    }
    while pi < p.len() and p[pi].unwrap() == "*" {
        pi = pi + 1
    }
    return pi == p.len()
}

fn eval_infix_arith(expr: str) to int {
    let chars: list[str] = expr.chars()
    let mut st: list[int] = []
    let mut cur: int = 0
    let mut op: str = "+"
    let mut i: int = 0
    while i < chars.len() {
        let ch: str = chars[i].unwrap()
        if ch.is_digit() {
            cur = cur * 10 + (ch.ord() - 48)
        }
        let is_end: bool = i == chars.len() - 1
        if (not ch.is_digit() and ch != " ") or is_end {
            if op == "+" {
                st = st.push(cur)
            } else if op == "-" {
                st = st.push(0 - cur)
            } else if op == "*" {
                let top: int = st[st.len() - 1].unwrap()
                st[st.len() - 1] = top * cur
            }
            if ch == "+" or ch == "-" or ch == "*" {
                op = ch
            }
            cur = 0
        }
        i = i + 1
    }
    let mut total: int = 0
    for v in st { total = total + v }
    return total
}

