fn normalize_posix_path(path: str) to str {
    let is_abs: bool = path.starts_with("/")
    let mut st: list[str] = []
    for seg in path.split("/") {
        if seg == "" or seg == "." {
            continue
        } else if seg == ".." {
            if st.len() > 0 and st[st.len() - 1].unwrap() != ".." {
                st = st.remove_at(st.len() - 1)
            } else if not is_abs {
                st = st.push("..")
            }
        } else {
            st = st.push(seg)
        }
    }
    if st.len() == 0 {
        if is_abs { return "/" } else { return "." }
    }
    let joined: str = st.join("/")
    if is_abs { return "/" + joined }
    return joined
}

fn snake_to_camel(s: str) to str {
    let mut out: str = ""
    let mut first: bool = true
    for part in s.split("_") {
        if part.len() == 0 { continue }
        let lo: str = part.to_lower()
        if first {
            out = out + lo
            first = false
        } else {
            out = out + lo.slice(0, 1).to_upper() + lo.slice(1, lo.chars_count())
        }
    }
