fn int_to_roman(n: int) to str {
    if n < 1 or n > 3999 { return "" }
    let vals: list[int] = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    let syms: list[str] = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
    let mut rem: int = n
    let mut out: str = ""
    let mut i: int = 0
    while i < vals.len() {
        let v: int = vals[i].unwrap()
        let sym: str = syms[i].unwrap()
