}

fn is_valid_iso_date(s: str) to bool {
    let parts: list[str] = s.split("-")
    if parts.len() != 3 { return false }
    let ys: str = parts[0].unwrap()
    let ms: str = parts[1].unwrap()
    let ds: str = parts[2].unwrap()
    if ys.len() != 4 or ms.len() != 2 or ds.len() != 2 { return false }
    if not ys.is_digit() or not ms.is_digit() or not ds.is_digit() { return false }
    let y: int = ys.to_int().unwrap()
    let m: int = ms.to_int().unwrap()
    let d: int = ds.to_int().unwrap()
    if m < 1 or m > 12 or d < 1 { return false }
    let leap: bool = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
    let mut max_d: int = 31
    if m == 4 or m == 6 or m == 9 or m == 11 { max_d = 30 }
    if m == 2 { if leap { max_d = 29 } else { max_d = 28 } }
    return d <= max_d
}

fn int_to_base36(n: int) to str {
    if n <= 0 { return "0" }
    let alpha: list[str] = "0123456789abcdefghijklmnopqrstuvwxyz".chars()
    let mut digits: list[str] = []
    let mut x: int = n
    while x > 0 {
        digits = digits.push(alpha[x % 36].unwrap())
        x = x / 36
    }
    return digits.reversed().join("")
}

fn strip_line_comments(code: str) to str {
    let cs: list[str] = code.chars()
    let n: int = cs.len()
    let mut out: str = ""
    let mut in_str: bool = false
    let mut in_cmt: bool = false
    let mut i: int = 0
    while i < n {
        let ch: str = cs[i].unwrap()
        if in_cmt {
            if ch == "\n" {
                in_cmt = false
                out = out + ch
            }
        } else if in_str {
            out = out + ch
            if ch == "\\" and i + 1 < n {
                i = i + 1
                out = out + cs[i].unwrap()
            } else if ch == "\"" {
                in_str = false
            }
        } else {
            if ch == "/" and i + 1 < n and cs[i + 1].unwrap() == "/" {
                in_cmt = true
                i = i + 1
            } else {
                if ch == "\"" { in_str = true }
                out = out + ch
            }
        }
        i = i + 1
    }
    return out
}

