            if nxt == "n" { out = out + "\n"
 i = i + 2
 continue }
            if nxt == "t" { out = out + "\t"
 i = i + 2
 continue }
            if nxt == "\\" { out = out + "\\"
 i = i + 2
 continue }
            if nxt == "\"" { out = out + "\""
 i = i + 2
 continue }
        }
