fn extract_balanced_paren(s: str) to str {
    let cs: list[str] = s.chars()
    let mut depth: int = 0
    let mut start: int = -1
    let mut i: int = 0
    while i < cs.len() {
        let ch: str = cs[i].unwrap()
        if ch == "(" {
            if depth == 0 { start = i + 1 }
            depth = depth + 1
        } else if ch == ")" and depth > 0 {
            depth = depth - 1
            if depth == 0 {
                return s.slice(start, i)
            }
        }
        i = i + 1
    }
    return ""
}

