query calculate_shipping(weight_grams: int, express: bool) to int {
    if weight_grams <= 0 { return 0 }
    let mut cost: int = 500
    if weight_grams > 1000 {
        cost = cost + (weight_grams - 1000) * 2
    }
    if express {
        cost = cost * 2
    }
    return cost
}

benchmarks.test_harness:
fn __vox_eval_harness() to str {
    assert(calculate_shipping(0, true) == 0)
    assert(calculate_shipping(800, false) == 500)
    assert(calculate_shipping(1250, true) == 2000)
    return "ok"
}

