query paginate_window(total: int, page: int, per_page: int) to list[int] {
    if total <= 0 or page < 1 or per_page <= 0 { return [0, 0] }
    let start: int = (page - 1) * per_page
    if start >= total { return [0, 0] }
    let mut end: int = start + per_page
    if end > total { end = total }
    return [start, end]
}

benchmarks.test_harness:
fn __vox_eval_harness() to str {
    assert(paginate_window(25, 2, 10) == [10, 20])
    assert(paginate_window(25, 3, 10) == [20, 25])
    assert(paginate_window(25, 4, 10) == [0, 0])
    return "ok"
}

