query normalize_slug(raw: str) to str {
    let mut parts: list[str] = []
    let mut cur: str = ""
    for ch in raw.to_lower().chars() {
        if ch.is_alnum() {
            cur = cur + ch
        } else {
            if cur.len() > 0 {
                parts = parts.push(cur)
                cur = ""
            }
        }
    }
    if cur.len() > 0 {
        parts = parts.push(cur)
    }
    return parts.join("-")
}

benchmarks.test_harness:
fn __vox_eval_harness() to str {
    assert(normalize_slug("  Hello, Vox 2.0 World!! ") == "hello-vox-2-0-world")
    assert(normalize_slug("---") == "")
    return "ok"
}

