query apply_coupon(code: str, subtotal_cents: int) to int {
    if subtotal_cents <= 0 { return 0 }
    if code == "SAVE10" and subtotal_cents >= 1000 {
        return subtotal_cents - subtotal_cents / 10
    }
    if code == "FLAT500" and subtotal_cents >= 2000 {
        return subtotal_cents - 500
    }
    if code == "VIP25" {
        return subtotal_cents - subtotal_cents / 4
    }
    return subtotal_cents
}

mutation apply_promo_discount(cents: int, pct: int) to int {
    if cents <= 0 { return 0 }
    let mut p: int = pct
    if p < 0 { p = 0 }
    if p > 80 { p = 80 }
    return cents - (cents * p) / 100
}

benchmarks.test_harness:
fn __vox_eval_harness() to str {
    assert(apply_promo_discount(1000, 15) == 850)
    assert(apply_promo_discount(1000, 95) == 200)
    assert(apply_promo_discount(500, -10) == 500)
    return "ok"
}

