mutation append_audit_tag(existing: str, tag: str) to str {
    let mut tags: list[str] = []
    for t in existing.split(",") {
        let clean: str = t.trim()
        if clean.len() > 0 and not tags.contains(clean) {
            tags = tags.push(clean)
        }
    }
    let nt: str = tag.trim()
    if nt.len() > 0 and not tags.contains(nt) {
        tags = tags.push(nt)
    }
    return tags.join(",")
}

benchmarks.test_harness:
fn __vox_eval_harness() to str {
    assert(append_audit_tag("v1,prod", "canary") == "v1,prod,canary")
    assert(append_audit_tag("v1, prod", "prod") == "v1,prod")
    assert(append_audit_tag("", "init") == "init")
    return "ok"
}

benchmarks.answer:
tool "build_doc_path: Build normalized markdown path" build_doc_path(dir: str, name: str) to str {
    let mut d: str = dir.trim()
    while d.starts_with("/") { d = d.slice(1, d.chars_count()) }
    while d.ends_with("/") { d = d.slice(0, d.chars_count() - 1) }
    let mut f: str = name.trim()
    if not f.ends_with(".md") { f = f + ".md" }
    if d.len() == 0 { return f }
    return d + "/" + f
}

benchmarks.test_harness:
fn __vox_eval_harness() to str {
    assert(build_doc_path("/docs/arch/", "memory") == "docs/arch/memory.md")
    assert(build_doc_path("", "readme.md") == "readme.md")
    return "ok"
}

